insert into public.courses (id, title, description, ai_instructions, icon, color, category, subcategory, locked, modules)
values (
  'course-atlas-cuerpo-humano',
  'Atlas del Cuerpo Humano: los 12 Sistemas',
  'Un diagrama vectorizado de referencia para cada uno de los 12 sistemas del cuerpo humano — consulta rápida y visual, complemento del curso de Anatomía y Fisiología Humana.',
  'Eres el Lagarto Mago, guía de este atlas visual de Oliver Academy. Este curso es de referencia rápida (un diagrama por sistema) — si el alumno quiere la explicación completa con ejemplos y ejercicios, dirígelo al curso Anatomía y Fisiología Humana.',
  '🗺️',
  '#0ea5e9',
  'Medicina',
  'Atlas Visual',
  false,
  '[{"id":1,"order":1,"type":"text","title":"🦴 Sistema esquelético","description":"Los 206 huesos del adulto: sostienen el cuerpo, protegen órganos vitales, almacenan minerales y producen células sanguíneas en la médula ósea.","content":"<h2>Sistema esquelético</h2><p>Los 206 huesos del adulto: sostienen el cuerpo, protegen órganos vitales, almacenan minerales y producen células sanguíneas en la médula ósea.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 240 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:300px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"120\" cy=\"35\" r=\"26\" fill=\"none\" stroke=\"#e2e8f0\" stroke-width=\"3\"/>\n<line x1=\"120\" y1=\"61\" x2=\"120\" y2=\"90\" stroke=\"#e2e8f0\" stroke-width=\"3\"/>\n<line x1=\"70\" y1=\"95\" x2=\"170\" y2=\"95\" stroke=\"#e2e8f0\" stroke-width=\"4\"/>\n<line x1=\"120\" y1=\"90\" x2=\"120\" y2=\"200\" stroke=\"#e2e8f0\" stroke-width=\"3\"/>\n<line x1=\"80\" y1=\"105\" x2=\"160\" y2=\"105\" stroke=\"#94a3b8\" stroke-width=\"2\"/><line x1=\"80\" y1=\"119\" x2=\"160\" y2=\"119\" stroke=\"#94a3b8\" stroke-width=\"2\"/><line x1=\"80\" y1=\"133\" x2=\"160\" y2=\"133\" stroke=\"#94a3b8\" stroke-width=\"2\"/><line x1=\"80\" y1=\"147\" x2=\"160\" y2=\"147\" stroke=\"#94a3b8\" stroke-width=\"2\"/><line x1=\"80\" y1=\"161\" x2=\"160\" y2=\"161\" stroke=\"#94a3b8\" stroke-width=\"2\"/><line x1=\"80\" y1=\"175\" x2=\"160\" y2=\"175\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n<line x1=\"70\" y1=\"95\" x2=\"55\" y2=\"220\" stroke=\"#e2e8f0\" stroke-width=\"3\"/>\n<line x1=\"170\" y1=\"95\" x2=\"185\" y2=\"220\" stroke=\"#e2e8f0\" stroke-width=\"3\"/>\n<rect x=\"75\" y=\"200\" width=\"90\" height=\"50\" fill=\"none\" stroke=\"#e2e8f0\" stroke-width=\"3\" rx=\"8\"/>\n<line x1=\"90\" y1=\"250\" x2=\"90\" y2=\"380\" stroke=\"#e2e8f0\" stroke-width=\"4\"/>\n<line x1=\"150\" y1=\"250\" x2=\"150\" y2=\"380\" stroke=\"#e2e8f0\" stroke-width=\"4\"/>\n<text x=\"200\" y=\"40\" fill=\"#94a3b8\" font-size=\"12\" font-family=\"sans-serif\">cráneo</text>\n<text x=\"200\" y=\"100\" fill=\"#94a3b8\" font-size=\"12\" font-family=\"sans-serif\">clavícula</text>\n<text x=\"200\" y=\"150\" fill=\"#94a3b8\" font-size=\"12\" font-family=\"sans-serif\">vértebras</text>\n<text x=\"200\" y=\"225\" fill=\"#94a3b8\" font-size=\"12\" font-family=\"sans-serif\">pelvis</text>\n<text x=\"200\" y=\"380\" fill=\"#94a3b8\" font-size=\"12\" font-family=\"sans-serif\">fémur/tibia</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Cuántos huesos tiene aproximadamente el esqueleto de un adulto?","options":["106","206","306","406"],"correctIndex":1},"comments":[]},{"id":2,"order":2,"type":"text","title":"💪 Sistema muscular","description":"Más de 600 músculos que se contraen (nunca \"empujan\") para mover el esqueleto, en pares opuestos como bíceps/tríceps.","content":"<h2>Sistema muscular</h2><p>Más de 600 músculos que se contraen (nunca \"empujan\") para mover el esqueleto, en pares opuestos como bíceps/tríceps.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 240 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:300px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"120\" cy=\"35\" r=\"24\" fill=\"#7f1d1d\"/>\n<path d=\"M85 65 Q120 55 155 65 L165 190 Q120 210 75 190 Z\" fill=\"#991b1b\"/>\n<path d=\"M75 75 Q55 100 60 160 Q75 165 78 140 Z\" fill=\"#b91c1c\"/>\n<path d=\"M165 75 Q185 100 180 160 Q165 165 162 140 Z\" fill=\"#b91c1c\"/>\n<path d=\"M85 190 Q90 260 85 320 Q100 325 105 260 Z\" fill=\"#b91c1c\"/>\n<path d=\"M155 190 Q150 260 155 320 Q140 325 135 260 Z\" fill=\"#b91c1c\"/>\n<text x=\"185\" y=\"70\" fill=\"#fca5a5\" font-size=\"11\" font-family=\"sans-serif\">deltoides</text>\n<text x=\"185\" y=\"140\" fill=\"#fca5a5\" font-size=\"11\" font-family=\"sans-serif\">bíceps</text>\n<text x=\"20\" y=\"150\" fill=\"#fca5a5\" font-size=\"11\" font-family=\"sans-serif\" text-anchor=\"start\">abdomen</text>\n<text x=\"185\" y=\"270\" fill=\"#fca5a5\" font-size=\"11\" font-family=\"sans-serif\">cuádriceps</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Cómo generan movimiento los músculos?","options":["Empujando los huesos","Contrayéndose y jalando el hueso al que están unidos","Creciendo permanentemente","No se conectan a huesos"],"correctIndex":1},"comments":[]},{"id":3,"order":3,"type":"text","title":"🫀 Sistema circulatorio (cardiovascular)","description":"El corazón bombea ≈5 litros de sangre por minuto en dos circuitos: uno corto hacia los pulmones, uno largo hacia todo el cuerpo.","content":"<h2>Sistema circulatorio (cardiovascular)</h2><p>El corazón bombea ≈5 litros de sangre por minuto en dos circuitos: uno corto hacia los pulmones, uno largo hacia todo el cuerpo.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 240 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:300px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<path d=\"M120 90 C90 50 30 60 30 110 C30 160 90 190 120 230 C150 190 210 160 210 110 C210 60 150 50 120 90 Z\" fill=\"#ef4444\"/>\n<line x1=\"120\" y1=\"90\" x2=\"120\" y2=\"30\" stroke=\"#3b82f6\" stroke-width=\"6\"/>\n<text x=\"130\" y=\"30\" fill=\"#93c5fd\" font-size=\"12\" font-family=\"sans-serif\">aorta</text>\n<line x1=\"60\" y1=\"70\" x2=\"30\" y2=\"20\" stroke=\"#f87171\" stroke-width=\"4\"/>\n<text x=\"15\" y=\"15\" fill=\"#fca5a5\" font-size=\"11\" font-family=\"sans-serif\">arterias</text>\n<line x1=\"180\" y1=\"70\" x2=\"210\" y2=\"20\" stroke=\"#3b82f6\" stroke-width=\"4\"/>\n<text x=\"185\" y=\"15\" fill=\"#93c5fd\" font-size=\"11\" font-family=\"sans-serif\">venas</text>\n<text x=\"120\" y=\"150\" fill=\"#450a0a\" font-size=\"13\" text-anchor=\"middle\" font-family=\"sans-serif\">4 cámaras</text>\n<text x=\"20\" y=\"270\" fill=\"#94a3b8\" font-size=\"11\" font-family=\"sans-serif\">≈5 litros de sangre bombeados por minuto</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Cuántas cámaras tiene el corazón humano?","options":["2","3","4","6"],"correctIndex":2},"comments":[]},{"id":4,"order":4,"type":"text","title":"🫁 Sistema respiratorio","description":"Aire → tráquea → bronquios → ≈300 millones de alvéolos por pulmón, donde ocurre el intercambio de oxígeno por dióxido de carbono.","content":"<h2>Sistema respiratorio</h2><p>Aire → tráquea → bronquios → ≈300 millones de alvéolos por pulmón, donde ocurre el intercambio de oxígeno por dióxido de carbono.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 240 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:300px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<rect x=\"105\" y=\"20\" width=\"14\" height=\"60\" fill=\"#38bdf8\"/>\n<text x=\"140\" y=\"45\" fill=\"#7dd3fc\" font-size=\"11\" font-family=\"sans-serif\">tráquea</text>\n<path d=\"M112 80 L60 110 Q40 160 60 230 Q90 250 105 220 L105 90 Z\" fill=\"#0ea5e9\"/>\n<path d=\"M112 80 L165 110 Q185 160 165 230 Q135 250 120 220 L120 90 Z\" fill=\"#0ea5e9\"/>\n<text x=\"30\" y=\"270\" fill=\"#7dd3fc\" font-size=\"11\" font-family=\"sans-serif\">pulmón izq.</text>\n<text x=\"140\" y=\"270\" fill=\"#7dd3fc\" font-size=\"11\" font-family=\"sans-serif\">pulmón der.</text>\n<circle cx=\"75\" cy=\"140\" r=\"3\" fill=\"#e0f2fe\"/><circle cx=\"85\" cy=\"158\" r=\"3\" fill=\"#e0f2fe\"/><circle cx=\"75\" cy=\"176\" r=\"3\" fill=\"#e0f2fe\"/><circle cx=\"85\" cy=\"194\" r=\"3\" fill=\"#e0f2fe\"/><circle cx=\"75\" cy=\"212\" r=\"3\" fill=\"#e0f2fe\"/>\n<text x=\"10\" y=\"20\" fill=\"#94a3b8\" font-size=\"10\" font-family=\"sans-serif\">≈300 millones de alvéolos por par de pulmones</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Dónde ocurre el intercambio de oxígeno y dióxido de carbono?","options":["En la tráquea","En los bronquios","En los alvéolos","En la faringe"],"correctIndex":2},"comments":[]},{"id":5,"order":5,"type":"text","title":"🧠 Sistema nervioso","description":"Cerebro y médula espinal (sistema nervioso central) conectados por una red de nervios periféricos a todo el cuerpo.","content":"<h2>Sistema nervioso</h2><p>Cerebro y médula espinal (sistema nervioso central) conectados por una red de nervios periféricos a todo el cuerpo.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 200 340\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:260px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<ellipse cx=\"100\" cy=\"55\" rx=\"55\" ry=\"48\" fill=\"#818cf8\"/>\n<text x=\"100\" y=\"60\" fill=\"#1e1b4b\" font-size=\"12\" text-anchor=\"middle\" font-family=\"sans-serif\">cerebro</text>\n<circle cx=\"55\" cy=\"105\" r=\"25\" fill=\"#94a3b8\"/>\n<text x=\"55\" y=\"109\" fill=\"#1e293b\" font-size=\"9\" text-anchor=\"middle\" font-family=\"sans-serif\">cerebelo</text>\n<rect x=\"90\" y=\"100\" width=\"20\" height=\"220\" fill=\"#6366f1\"/>\n<text x=\"120\" y=\"130\" fill=\"#c7d2fe\" font-size=\"11\" font-family=\"sans-serif\">médula espinal</text>\n<line x1=\"90\" y1=\"140\" x2=\"40\" y2=\"155\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"110\" y1=\"140\" x2=\"160\" y2=\"155\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"90\" y1=\"168\" x2=\"40\" y2=\"183\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"110\" y1=\"168\" x2=\"160\" y2=\"183\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"90\" y1=\"196\" x2=\"40\" y2=\"211\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"110\" y1=\"196\" x2=\"160\" y2=\"211\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"90\" y1=\"224\" x2=\"40\" y2=\"239\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"110\" y1=\"224\" x2=\"160\" y2=\"239\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"90\" y1=\"252\" x2=\"40\" y2=\"267\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"110\" y1=\"252\" x2=\"160\" y2=\"267\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"90\" y1=\"280\" x2=\"40\" y2=\"295\" stroke=\"#a5b4fc\" stroke-width=\"2\"/><line x1=\"110\" y1=\"280\" x2=\"160\" y2=\"295\" stroke=\"#a5b4fc\" stroke-width=\"2\"/>\n<text x=\"120\" y=\"320\" fill=\"#c7d2fe\" font-size=\"11\" font-family=\"sans-serif\">nervios periféricos</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Qué forma el sistema nervioso central?","options":["Solo los nervios periféricos","El cerebro y la médula espinal","Solo el cerebelo","Los músculos y huesos"],"correctIndex":1},"comments":[]},{"id":6,"order":6,"type":"text","title":"🍽️ Sistema digestivo","description":"Un tubo de ≈9 metros — boca a intestino grueso — con hígado, vesícula y páncreas ayudando a degradar y absorber el alimento.","content":"<h2>Sistema digestivo</h2><p>Un tubo de ≈9 metros — boca a intestino grueso — con hígado, vesícula y páncreas ayudando a degradar y absorber el alimento.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 200 340\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:260px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"60\" cy=\"25\" r=\"10\" fill=\"#facc15\"/>\n<text x=\"80\" y=\"30\" fill=\"#fde68a\" font-size=\"10\" font-family=\"sans-serif\">boca</text>\n<line x1=\"60\" y1=\"35\" x2=\"60\" y2=\"80\" stroke=\"#facc15\" stroke-width=\"6\"/>\n<text x=\"80\" y=\"60\" fill=\"#fde68a\" font-size=\"10\" font-family=\"sans-serif\">esófago</text>\n<path d=\"M60 80 Q30 100 40 140 Q55 155 80 140 Q95 110 60 80 Z\" fill=\"#f59e0b\"/>\n<text x=\"95\" y=\"115\" fill=\"#fde68a\" font-size=\"10\" font-family=\"sans-serif\">estómago</text>\n<path d=\"M55 145 Q30 180 60 210 Q90 230 55 250 Q30 265 70 280 Q100 290 60 300\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<text x=\"100\" y=\"230\" fill=\"#fde68a\" font-size=\"10\" font-family=\"sans-serif\">intestino delgado</text>\n<path d=\"M60 300 Q120 310 140 260 Q150 200 130 150\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<text x=\"145\" y=\"200\" fill=\"#fde68a\" font-size=\"10\" font-family=\"sans-serif\">intestino grueso</text>\n<ellipse cx=\"130\" cy=\"110\" rx=\"22\" ry=\"16\" fill=\"#b45309\"/>\n<text x=\"155\" y=\"108\" fill=\"#fde68a\" font-size=\"10\" font-family=\"sans-serif\">hígado</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Dónde ocurre principalmente la absorción de nutrientes?","options":["En la boca","En el estómago","En el intestino delgado","En el esófago"],"correctIndex":2},"comments":[]},{"id":7,"order":7,"type":"text","title":"🧴 Sistema tegumentario (piel)","description":"El órgano más grande del cuerpo: epidermis, dermis y tejido subcutáneo, con funciones de protección y regulación de temperatura.","content":"<h2>Sistema tegumentario (piel)</h2><p>El órgano más grande del cuerpo: epidermis, dermis y tejido subcutáneo, con funciones de protección y regulación de temperatura.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 400 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:420px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<rect x=\"20\" y=\"20\" width=\"360\" height=\"30\" rx=\"6\" fill=\"#fbbf9d\"/>\n<rect x=\"20\" y=\"55\" width=\"360\" height=\"45\" rx=\"6\" fill=\"#f2a586\"/>\n<rect x=\"20\" y=\"105\" width=\"360\" height=\"55\" rx=\"6\" fill=\"#fde68a\" opacity=\"0.85\"/>\n<text x=\"392\" y=\"39\" fill=\"#fde68a\" font-size=\"13\" text-anchor=\"end\" font-family=\"sans-serif\">Epidermis</text>\n<text x=\"392\" y=\"82\" fill=\"#fde68a\" font-size=\"13\" text-anchor=\"end\" font-family=\"sans-serif\">Dermis</text>\n<text x=\"392\" y=\"137\" fill=\"#fde68a\" font-size=\"13\" text-anchor=\"end\" font-family=\"sans-serif\">Tejido subcutáneo</text>\n<circle cx=\"260\" cy=\"75\" r=\"5\" fill=\"#dc2626\" opacity=\"0.7\"/>\n<text x=\"260\" y=\"95\" fill=\"#e2e8f0\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">glándula sudorípara</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Cuál es la capa más externa de la piel?","options":["Dermis","Epidermis","Tejido subcutáneo","Miocardio"],"correctIndex":1},"comments":[]},{"id":8,"order":8,"type":"text","title":"⚗️ Sistema endocrino","description":"Glándulas que liberan hormonas a la sangre: hipófisis, tiroides, suprarrenales y páncreas, entre otras.","content":"<h2>Sistema endocrino</h2><p>Glándulas que liberan hormonas a la sangre: hipófisis, tiroides, suprarrenales y páncreas, entre otras.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 240 400\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:260px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<ellipse cx=\"120\" cy=\"60\" rx=\"35\" ry=\"42\" fill=\"#1e293b\" stroke=\"#475569\"/>\n<circle cx=\"120\" cy=\"45\" r=\"6\" fill=\"#facc15\"/>\n<text x=\"170\" y=\"48\" fill=\"#facc15\" font-size=\"12\" font-family=\"sans-serif\">Hipófisis</text>\n<rect x=\"100\" y=\"120\" width=\"40\" height=\"55\" rx=\"10\" fill=\"#1e293b\" stroke=\"#475569\"/>\n<circle cx=\"120\" cy=\"130\" r=\"6\" fill=\"#38bdf8\"/>\n<text x=\"170\" y=\"133\" fill=\"#38bdf8\" font-size=\"12\" font-family=\"sans-serif\">Tiroides</text>\n<circle cx=\"105\" cy=\"220\" r=\"7\" fill=\"#f472b6\"/>\n<circle cx=\"135\" cy=\"220\" r=\"7\" fill=\"#f472b6\"/>\n<text x=\"170\" y=\"224\" fill=\"#f472b6\" font-size=\"12\" font-family=\"sans-serif\">Suprarrenales</text>\n<rect x=\"90\" y=\"250\" width=\"60\" height=\"20\" rx=\"8\" fill=\"#1e293b\" stroke=\"#475569\"/>\n<circle cx=\"120\" cy=\"260\" r=\"6\" fill=\"#4ade80\"/>\n<text x=\"170\" y=\"264\" fill=\"#4ade80\" font-size=\"12\" font-family=\"sans-serif\">Páncreas</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Qué glándula produce insulina?","options":["Tiroides","Hipófisis","Páncreas","Suprarrenales"],"correctIndex":2},"comments":[]},{"id":9,"order":9,"type":"text","title":"💧 Sistema renal (urinario)","description":"Riñones, uréteres, vejiga y uretra — filtran la sangre y regulan el balance de líquidos y el pH del cuerpo.","content":"<h2>Sistema renal (urinario)</h2><p>Riñones, uréteres, vejiga y uretra — filtran la sangre y regulan el balance de líquidos y el pH del cuerpo.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 400 160\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:420px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<path d=\"M40 40 a25 30 0 1 0 0.1 0\" fill=\"#a78bfa\"/>\n<text x=\"40\" y=\"30\" fill=\"#e2e8f0\" font-size=\"12\" text-anchor=\"middle\" font-family=\"sans-serif\">Riñón</text>\n<line x1=\"55\" y1=\"65\" x2=\"150\" y2=\"100\" stroke=\"#a78bfa\" stroke-width=\"4\"/>\n<ellipse cx=\"200\" cy=\"115\" rx=\"45\" ry=\"30\" fill=\"#818cf8\"/>\n<text x=\"200\" y=\"119\" fill=\"#0f172a\" font-size=\"12\" text-anchor=\"middle\" font-family=\"sans-serif\">Vejiga</text>\n<line x1=\"245\" y1=\"120\" x2=\"330\" y2=\"120\" stroke=\"#818cf8\" stroke-width=\"4\"/>\n<text x=\"330\" y=\"110\" fill=\"#c7d2fe\" font-size=\"11\" font-family=\"sans-serif\">uretra</text>\n<path d=\"M330 40 a25 30 0 1 1 -0.1 0\" fill=\"#a78bfa\"/>\n<text x=\"330\" y=\"30\" fill=\"#e2e8f0\" font-size=\"12\" text-anchor=\"middle\" font-family=\"sans-serif\">Riñón</text>\n<line x1=\"315\" y1=\"65\" x2=\"250\" y2=\"100\" stroke=\"#a78bfa\" stroke-width=\"4\"/>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Qué tubo conecta el riñón con la vejiga?","options":["La uretra","El uréter","La aorta","El esófago"],"correctIndex":1},"comments":[]},{"id":10,"order":10,"type":"text","title":"♂️ Sistema reproductor masculino","description":"Testículos, epidídimo y pene — produce espermatozoides y testosterona.","content":"<h2>Sistema reproductor masculino</h2><p>Testículos, epidídimo y pene — produce espermatozoides y testosterona.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 220 170\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:260px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"90\" cy=\"70\" r=\"18\" fill=\"#38bdf8\"/><circle cx=\"125\" cy=\"70\" r=\"18\" fill=\"#38bdf8\"/>\n<text x=\"107\" y=\"105\" fill=\"#e0f2fe\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">testículos</text>\n<line x1=\"107\" y1=\"52\" x2=\"107\" y2=\"20\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n<rect x=\"80\" y=\"10\" width=\"55\" height=\"14\" rx=\"7\" fill=\"#0ea5e9\"/>\n<text x=\"107\" y=\"150\" fill=\"#e0f2fe\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">pene / uretra</text>\n<line x1=\"107\" y1=\"115\" x2=\"107\" y2=\"140\" stroke=\"#0ea5e9\" stroke-width=\"4\"/>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Qué órgano produce los espermatozoides?","options":["El pene","Los testículos","La próstata","El epidídimo únicamente"],"correctIndex":1},"comments":[]},{"id":11,"order":11,"type":"text","title":"♀️ Sistema reproductor femenino","description":"Ovarios, trompas de Falopio, útero y vagina — produce óvulos y aloja el desarrollo fetal.","content":"<h2>Sistema reproductor femenino</h2><p>Ovarios, trompas de Falopio, útero y vagina — produce óvulos y aloja el desarrollo fetal.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 220 170\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:260px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"70\" cy=\"60\" r=\"12\" fill=\"#f472b6\"/><circle cx=\"150\" cy=\"60\" r=\"12\" fill=\"#f472b6\"/>\n<text x=\"70\" y=\"45\" fill=\"#fbcfe8\" font-size=\"10\" text-anchor=\"middle\" font-family=\"sans-serif\">ovario</text>\n<path d=\"M70 72 q40 15 80 -12\" stroke=\"#f472b6\" stroke-width=\"3\" fill=\"none\"/>\n<text x=\"110\" y=\"100\" fill=\"#fbcfe8\" font-size=\"10\" text-anchor=\"middle\" font-family=\"sans-serif\">trompas de Falopio</text>\n<ellipse cx=\"110\" cy=\"120\" rx=\"30\" ry=\"22\" fill=\"#ec4899\"/>\n<text x=\"110\" y=\"124\" fill=\"#fdf2f8\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">útero</text>\n<rect x=\"98\" y=\"142\" width=\"24\" height=\"20\" fill=\"#ec4899\"/>\n<text x=\"110\" y=\"167\" fill=\"#fbcfe8\" font-size=\"10\" text-anchor=\"middle\" font-family=\"sans-serif\">vagina</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Dónde se desarrolla normalmente el feto durante el embarazo?","options":["En los ovarios","En las trompas de Falopio","En el útero","En la vagina"],"correctIndex":2},"comments":[]},{"id":12,"order":12,"type":"text","title":"🛡️ Sistema linfático e inmunológico","description":"Ganglios, bazo y timo — drena líquido de los tejidos y defiende al cuerpo de infecciones.","content":"<h2>Sistema linfático e inmunológico</h2><p>Ganglios, bazo y timo — drena líquido de los tejidos y defiende al cuerpo de infecciones.</p><div style=\"text-align:center\"><svg viewBox=\"0 0 400 200\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-width:420px;display:block;margin:1rem auto;background:#0f172a;border-radius:12px\">\n<circle cx=\"200\" cy=\"40\" r=\"10\" fill=\"#34d399\"/>\n<text x=\"200\" y=\"24\" fill=\"#a7f3d0\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">ganglios cervicales</text>\n<circle cx=\"80\" cy=\"110\" r=\"10\" fill=\"#34d399\"/>\n<text x=\"80\" y=\"95\" fill=\"#a7f3d0\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">timo</text>\n<ellipse cx=\"200\" cy=\"120\" rx=\"22\" ry=\"30\" fill=\"#10b981\"/>\n<text x=\"200\" y=\"124\" fill=\"#022c22\" font-size=\"10\" text-anchor=\"middle\" font-family=\"sans-serif\">bazo</text>\n<circle cx=\"130\" cy=\"170\" r=\"9\" fill=\"#34d399\"/>\n<circle cx=\"270\" cy=\"170\" r=\"9\" fill=\"#34d399\"/>\n<text x=\"130\" y=\"195\" fill=\"#a7f3d0\" font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\">ganglios inguinales</text>\n</svg></div><p class=\"text-sm\" style=\"opacity:.7\">Diagrama de referencia — para la explicación completa de este sistema, con ejemplos y ejercicios, ve al curso <a href=\"/learn/course-medicina-anatomia\" target=\"_blank\" rel=\"noopener\">Anatomía y Fisiología Humana</a>.</p>","exercises":[],"resources":[],"noChat":true,"quiz":{"question":"¿Qué órgano filtra la sangre y almacena glóbulos blancos de reserva?","options":["El timo","El bazo","Los riñones","El páncreas"],"correctIndex":1},"comments":[]}]'::jsonb
